/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3.12 -c 'from solution import TTLCache

def check(name, fn):
    try: fn()
    except Exception as e: print(\"FAIL\", name, type(e).__name__, str(e))
    else: print(\"PASS\", name)
def eq(a,b):
    assert a == b, repr(a)+\" "'!= "+repr(b)
def caps():
    for v in [True,False,0,-1,1.5,"2",None]:
        try: TTLCache(v,lambda:0)
        except ValueError: continue
        raise AssertionError("accepted "+repr(v))
check("capacity validation",caps)
def expiry():
    n=[0]; c=TTLCache(2,lambda:n[0]); c.set("a",1,1); n[0]=1; eq(c.get("a","missing"),"missing")
check("exact expiry boundary",expiry)
def cleanup(op):
    n=[0]; c=TTLCache(2,lambda:n[0]); c.set("a",1,1); n[0]=2
    if op=="get": c.get("missing")
    if op=="set": c.set("b",2,10)
    eq(len(c),1 if op=="set" else 0)
for op in ["len","get","set"]: check("cleanup via "+op,lambda op=op:cleanup(op))
def invalid(ttl):
    c=TTLCache(1,lambda:0); c.set("a",1,10)
    try: c.set("b",2,ttl)
    except ValueError: pass
    except Exception as e: raise AssertionError(type(e).__name__+" contents="+repr(c.items))
    else: raise AssertionError("accepted; contents="+repr(c.items))
    eq(c.get("a"),1)
for ttl in [True,False,-1,float("inf"),float("-inf"),float("nan"),"1",None]: check("invalid TTL "+repr(ttl),lambda ttl=ttl:invalid(ttl))
def zero():
    c=TTLCache(2,lambda:0); c.set("a",1,10); c.set("a",2,0); eq(len(c),0)
check("zero TTL removal",zero)
def lru():
    c=TTLCache(2,lambda:0); c.set("a",1,10); c.set("b",2,10); c.get("a"); c.set("c",3,10); eq(c.get("a"),1); eq(c.get("b"),None)
check("get updates LRU",lru)
def replace():
    c=TTLCache(2,lambda:0); c.set("a",1,10); c.set("b",2,10); c.set("b",3,20); eq(c.get("a"),1); eq(len(c),2)
check("replacement preserves other keys",replace)
def falsy(v):
    c=TTLCache(1,lambda:0); c.set("a",v,10); assert c.get("a","default") is v
for v in [None,0,False,""]: check("falsy "+repr(v),lambda v=v:falsy(v))'"'"
